import {network,solve} from './solver.js';
const $=id=>document.getElementById(id);let open=false,discovered=false,current; const reducedMotion=globalThis.matchMedia?.('(prefers-reduced-motion: reduce)'); let moving=!reducedMotion?.matches;const fmt=(v,d=1)=>v.toLocaleString('pl-PL',{maximumFractionDigits:d,minimumFractionDigits:d});const line=[[115,193,355,87],[405,87,645,193],[115,217,355,323],[405,323,645,217],[380,103,380,307]];const labels=[[220,110],[540,110],[220,294],[540,294],[463,199]];
function update(){
 for(const id of ['comparisonSection','planMetric','theory','choice'])$(id).hidden=!discovered;
 $('motion').setAttribute('aria-pressed',moving);$('motion').textContent=moving?'Zatrzymaj ruch na mapie':'Pokaż ruch na mapie';
 $('shortcutHelp').textContent=discovered?'Porównanie poniżej pokazuje wynik z otwartym i zamkniętym skrótem.':'Skrót łączy A z B. Otwórz go, aby zobaczyć wynik.';
const n=+$('demand').value,a=+$('slope').value,b=+$('fixed').value,k=+$('cost').value;if(![a,b,k].every(Number.isFinite)||a<0||b<0||k<0)return;const edges=network(a,b,k),social=document.querySelector('input[name=mode]:checked').value==='social';const wc=solve(n,false,edges),wo=solve(n,true,edges),sc=solve(n,false,edges,true),so=solve(n,true,edges,true),r=social?(open?so:sc):(open?wo:wc);current={demand:n,edges,open,mode:social?'social':'equilibrium',closed:{equilibrium:wc,social:sc},opened:{equilibrium:wo,social:so}};$('demandValue').textContent=fmt(n,0);$('shortcut').setAttribute('aria-pressed',open);$('toggleText').textContent=open?'Zamknij skrót':'Otwórz skrót';$('modeLabel').textContent=social?'Najkrótszy łączny czas':'Kierowcy wybierają trasę';$('average').innerHTML=fmt(r.average)+' <small>min</small>';$('total').innerHTML=fmt(r.total/60,0)+' <small>godz.</small>';const w=open?wo:wc,s=open?so:sc;$('price').innerHTML=fmt(s.average?w.average/s.average:1,2)+'<small> × optimum</small>';
$('roads').innerHTML=edges.map((e,i)=>{const [x1,y1,x2,y2]=line[i],inactive=i===4&&!open;return `<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${inactive?'#b8b3a4':e.a?'#b65b3f':i===4?'#df9d29':'#52736b'}" stroke-width="${inactive?2:5+13*r.flows[i]/n}" ${inactive?'stroke-dasharray="6 7"':'marker-end="url(#arrow)"'}/>`}).join('');$('traffic').innerHTML=moving?edges.map((e,i)=>{if((i===4&&!open)||r.flows[i]<1e-6)return '';const count=Math.max(1,Math.round(8*r.flows[i]/n)),[x1,y1,x2,y2]=line[i];return Array.from({length:count},(_,j)=>`<circle r="2.5" fill="#fff9e9"><animateMotion dur="6s" begin="${-6*j/count}s" repeatCount="indefinite" path="M ${x1} ${y1} L ${x2} ${y2}"/></circle>`).join('')}).join(''):'';
$('edgeSummary').innerHTML=edges.map((e,i)=>`<div><strong>${e.from} → ${e.to}</strong><span>${i===4&&!open?'Zamknięta':fmt(r.edgeTimes[i])+' min · '+fmt(r.flows[i],0)+' poj./h'}</span></div>`).join('');
$('roadLabels').innerHTML=edges.map((e,i)=>{const [x,y]=labels[i];return `<rect class="road-bg" x="${x-68}" y="${y-17}" width="136" height="43" rx="5"/><text class="road-label" x="${x}" y="${y}">${i===4&&!open?'zamknięta':fmt(r.edgeTimes[i])+' min'}</text><text class="road-sub" x="${x}" y="${y+17}">${i===4&&!open?'A → B':fmt(r.flows[i],0)+' poj./h · '+(e.a?'zależnie od ruchu':'bez zmian')}</text>`}).join('');
const delta=wo.average-wc.average,paradox=delta>1e-6;$('verdict').className='verdict'+(paradox&&open?' bad':'');$('verdict').textContent=!discovered?`Średni czas przejazdu: ${fmt(wc.average)} min. Otwórz skrót, żeby porównać wyniki.`:social?`Przy rozkładzie minimalizującym łączny czas przejazdu średnia wynosi ${fmt(r.average)} min.`:open?`Po otwarciu skrótu średni czas ${delta>1e-6?'wzrósł o '+fmt(delta)+' min':delta< -1e-6?'skrócił się o '+fmt(-delta)+' min':'nie zmienił się'}. Bez skrótu: ${fmt(wc.average)} min. Ze skrótem: ${fmt(wo.average)} min.`:`Skrót jest zamknięty. Średni czas wynosi ${fmt(wc.average)} min; przy otwartym skrócie wyniósłby ${fmt(wo.average)} min.`;
$('comparison').innerHTML=`<tr><td>Wybór kierowców</td><td>${fmt(wc.average)} min</td><td>${fmt(wo.average)} min</td></tr><tr><td>Najkrótszy łączny czas</td><td>${fmt(sc.average)} min</td><td>${fmt(so.average)} min</td></tr>`;$('routeTitle').textContent=social?'Przydzielone trasy':'Wybrane trasy';$('routes').innerHTML=r.routes.map((p,i)=>{const name=['S',...p.map(e=>edges[e].to)].join(' → '),f=r.routeFlows[i];return `<div class="route"><span>${name}<small>${f>1e-6?'używana':'nieużywana'} · ${fmt(r.times[i])} min</small></span><span>${fmt(f,0)} poj./h <small>${fmt(f/n*100)}%</small></span><div class="bar"><span style="width:${100*f/n}%"></span></div></div>`}).join('');$('validation').textContent=social?'Ten rozkład minimalizuje łączny czas przejazdu. Wymaga przydzielenia tras; część kierowców wybrałaby samodzielnie inną drogę.':`Przy tym rozkładzie ruchu zmiana trasy nie daje już zauważalnej oszczędności czasu. Taką sytuację nazywamy równowagą Wardropa. Dokładność obliczeń: ${fmt(r.gap,6)} min możliwej poprawy średnio.`;
}
$('motion').onclick=()=>{moving=!moving;update()};reducedMotion?.addEventListener?.('change',e=>{if(e.matches){moving=false;update()}});
$('shortcut').onclick=()=>{open=!open;if(open)discovered=true;update()};document.querySelectorAll('input').forEach(el=>el.addEventListener('input',update));$('reset').onclick=()=>{$('demand').value=4000;$('slope').value=.01;$('fixed').value=45;$('cost').value=0;open=false;discovered=false;document.querySelector('input[value=equilibrium]').checked=true;update()};$('export').onclick=()=>{const blob=new Blob([JSON.stringify(current,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='braess-experiment.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};update();
